{"script":"function extractColors() {
  const results = {};

  // Look for color buttons/links
  const colorButtons = document.querySelectorAll('[aria-label*="iMac"], [aria-label*="color"], [aria-label*="Color"], [aria-label*="Green"], [aria-label*="Yellow"], [aria-label*="Orange"], [aria-label*="Pink"], [aria-label*="Purple"], [aria-label*="Blue"], [aria-label*="Silver"]');
  results.colorButtons = Array.from(colorButtons).map(el => ({
    tag: el.tagName,
    ariaLabel: el.getAttribute('aria-label'),
    text: el.textContent.trim().substring(0, 100),
    className: el.className
  }));

  // Look for color swatch images
  const allImages = document.querySelectorAll('img, picture');
  results.colorImages = [];
  allImages.forEach(el => {
    const alt = el.getAttribute('alt') || '';
