      results.colorImages.push({tag: el.tagName, alt: alt});
    }
  });

  // Look for color swatches
  const swatches = document.querySelectorAll('[class*="swatch"], [class*="color-"], [data-color], [data-color-name]');
  results.swatches = Array.from(swatches).map(el => ({
    tag: el.tagName,
    className: el.className,
    ariaLabel: el.getAttribute('aria-label'),
    dataColor: el.getAttribute('data-color'),
    dataColorName: el.getAttribute('data-color-name')
  }));

  return results;
}
return extractColors();"}

